// RPi Express (smartfarm-rpi, port 3001 또는 1880 nginx) 의 /api/sync/status 호출
// MQTT 메시지의 farmId 를 응답에 포함하기 위해 보존
const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || global.get('FARM_ID') || env.get('FARM_ID') || 'farm_0001';

msg._farmId = farmId;
msg.method = 'GET';
msg.url = 'http://localhost:1880/api/sync/status';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = null;

node.status({ fill: 'blue', shape: 'dot', text: 'GET ' + farmId });
return msg;

// HTTP 응답 → MQTT smartfarm/{farmId}/sync/status
const farmId = msg._farmId || 'farm_0001';

let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) {
        node.warn('sync/status 응답 파싱 실패: ' + e.message);
        return null;
    }
}

// data.success 가 true 이면 data.data 가 실제 sync status
const statusData = (data && data.success && data.data) ? data.data : (data || {});

msg.topic = 'smartfarm/' + farmId + '/sync/status';
msg.payload = {
    ...statusData,
    timestamp: new Date().toISOString(),
};
msg.qos = 1;
msg.retain = false;

node.status({
    fill: 'green', shape: 'dot',
    text: 'unsynced=' + (statusData.unsynced || 0) + ' synced=' + (statusData.synced || 0)
});
return msg;

// MQTT payload.action (start/stop/skip) → /api/sync/{action} POST 호출
const data = msg.payload || {};
const action = data.action;

if (!['start', 'stop', 'skip'].includes(action)) {
    node.warn('잘못된 sync action: ' + action);
    return null;
}

const topicParts = (msg.topic || '').split('/');
const farmId = topicParts[1] || 'farm_0001';

msg.method = 'POST';
msg.url = 'http://localhost:1880/api/sync/' + action;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { operator: data.operator || 'unknown', farmId };
msg._farmId = farmId;
msg._action = action;

node.status({ fill: 'blue', shape: 'dot', text: action + ' ' + farmId });
return msg;

const farmId = msg._farmId || 'farm_0001';
const action = msg._action || '?';
const ok = msg.statusCode === 200 && msg.payload && msg.payload.success !== false;

node.status({
    fill: ok ? 'green' : 'red',
    shape: 'dot',
    text: action + ' ' + (ok ? 'OK' : 'fail') + ' ' + farmId
});

if (ok) {
    node.warn('sync/' + action + ' 완료: ' + farmId);
} else {
    node.warn('sync/' + action + ' 실패: ' + farmId + ' status=' + msg.statusCode);
}

// 명령 후 status 자동 갱신을 위해 sync/query 트리거 (1초 대기)
setTimeout(function() {
    node.send({
        method: 'GET',
        url: 'http://localhost:1880/api/sync/status',
        headers: { 'Content-Type': 'application/json' },
        payload: null,
        _farmId: farmId,
    });
}, 1000);

return null;
